    31→import org.apache.druid.java.util.common.StringUtils;
    32→import org.apache.druid.js.JavaScriptConfig;
    33→import org.apache.druid.segment.BaseObjectColumnValueSelector;
    34→import org.apache.druid.segment.ColumnSelectorFactory;
    35→import org.apache.druid.segment.ColumnValueSelector;
    36→import org.apache.druid.segment.column.ValueType;
    37→import org.checkerframework.checker.nullness.qual.EnsuresNonNull;
    38→import org.checkerframework.checker.nullness.qual.MonotonicNonNull;
    39→import org.checkerframework.checker.nullness.qual.Nullable;
    40→import org.mozilla.javascript.Context;
    41→import org.mozilla.javascript.ContextAction;
    42→import org.mozilla.javascript.ContextFactory;
    43→import org.mozilla.javascript.Function;
    44→import org.mozilla.javascript.ScriptableObject;
    45→
    46→import java.lang.reflect.Array;
